{
  "name": "Sunbrick 多通道可调光谱LED光源模块",
  "name_en": "Sunbrick Multi-Channel Tunable Spectrum LED Light Module",
  "manufacturer": "G2V",
  "description": "Sunbrick 是一种多通道、可联网的 LED 光源模块，可按通道调节输出值、设置整体强度因子、加载预设光谱，并监测模块节点温度。它适合在实验室中提供可编程、可重复的光照条件，用于光学测试、材料表征及其他需要可调光谱照明的实验。",
  "description_en": "The Sunbrick is a multi-channel, networkable LED light module that allows per-channel output control, overall intensity adjustment, preset spectrum loading, and node temperature monitoring. It is used in laboratories to provide programmable and repeatable illumination for optical testing, material characterization, and other experiments requiring tunable spectral lighting.",
  "actions": [
    {
      "action_name": "auto-set_channel_value",
      "description": "设置指定节点的LED通道输出值",
      "description_en": "set the output value of a selected LED channel on a selected node"
    },
    {
      "action_name": "auto-set_intensity_factor",
      "description": "设置节点的整体强度因子",
      "description_en": "set the overall intensity factor of a node"
    },
    {
      "action_name": "auto-turn_off",
      "description": "关闭所有节点的所有通道输出",
      "description_en": "turn off all channels on all nodes"
    },
    {
      "action_name": "auto-set_spectrum",
      "description": "设置设备的光谱配置",
      "description_en": "set the device spectrum configuration"
    },
    {
      "action_name": "auto-setup_network_arbitration",
      "description": "执行网络仲裁并自动建立Sunbrick模块阵列通信",
      "description_en": "perform network arbitration and automatically establish communication with a Sunbrick module array"
    }
  ],
  "tag_hints": [
    "programmable LED illumination",
    "spectral tuning",
    "multi-channel light source",
    "intensity control",
    "networked light modules",
    "temperature monitoring",
    "optical testing"
  ]
}

